58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /** Minimal syntactic check for an email address: a non-empty local part, a single
68	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
73	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
74	
75	    /** Disposable email domains that are rejected: an owner whose email domain matches one of
76	     *  these (case-insensitively) is refused with 400. */
77	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
78	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
79	
80	    /** Dedicated audit logger; emits an audit line on successful owner create. */
81	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
82	
83	    private final ClinicService clinicService;
84	
85	    private final OwnerMapper ownerMapper;
86	
87	    private final PetMapper petMapper;
88	
89	    private final VisitMapper visitMapper;
90	
91	    private final TelephoneNormalizer telephoneNormalizer;
92	
93	    private final AddressNormalizer addressNormalizer;
94	
95	    private final CityRegionResolver cityRegionResolver;
96	
97	    private final HouseholdResolver householdResolver;
98	
99	    public OwnerRestControllerV1(ClinicService clinicService,
100	                                 OwnerMapper ownerMapper,
101	                                 PetMapper petMapper,
102	                                 VisitMapper visitMapper,
103	                                 TelephoneNormalizer telephoneNormalizer,
104	                                 AddressNormalizer addressNormalizer,
105	                                 CityRegionResolver cityRegionResolver,
106	                                 HouseholdResolver householdResolver) {
107	        this.clinicService = clinicService;
108	        this.ownerMapper = ownerMapper;
109	        this.petMapper = petMapper;
110	        this.visitMapper = visitMapper;
111	        this.telephoneNormalizer = telephoneNormalizer;
112	        this.addressNormalizer = addressNormalizer;
113	        this.cityRegionResolver = cityRegionResolver;
114	        this.householdResolver = householdResolver;
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
120	        Collection<Owner> owners;
121	        if (lastName != null) {
122	            owners = this.clinicService.findOwnerByLastName(lastName);
123	        } else {
124	            owners = this.clinicService.findAllOwners();
125	        }
126	        if (owners.isEmpty()) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
135	        Owner owner = this.clinicService.findOwnerById(ownerId);
136	        if (owner == null) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
145	        HttpHeaders headers = new HttpHeaders();
146	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
147	        if (owner.getRegistrationDate() == null) {
148	            owner.setRegistrationDate(LocalDate.now());
149	        }
150	        // A supplied registration date may not be later than the server's current date.
151	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
152	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
153	        }
154	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
155	        LocalDate registrationDate = owner.getRegistrationDate();
156	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
157	            .map(Owner::getRegistrationDate)
158	            .filter(registrationDate::equals)
159	            .count();
160	        if (ownersCreatedThatDay >= 100) {
161	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
162	        }
163	        String address = addressNormalizer.normalize(owner.getAddress());
164	        if (address.isBlank()) {
165	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
166	        }
167	        owner.setAddress(address);
168	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
169	        if (telephone == null) {
170	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
171	        }
172	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
173	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
174	        }
175	        owner.setTelephone(telephone);
176	        String email = owner.getEmail();
177	        if (email != null) {
178	            email = email.trim();
179	            if (!EMAIL_PATTERN.matcher(email).matches()) {
180	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
181	            }
182	            String domain = email.substring(email.indexOf('@') + 1).toLowerCase(Locale.ROOT);
183	            if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
184	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
185	            }
186	            owner.setEmail(email.toLowerCase(Locale.ROOT));
187	        }
188	        // A postcode is optional, but when supplied it must be four digits and valid for the
189	        // owner's city per the fixed region table; a city with no known region accepts any
190	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
191	        String postcode = owner.getPostcode();
192	        if (postcode != null) {
193	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
194	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
195	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
196	            }
197	        }
198	        // The owner's telephone and email are now in their canonical, stored form.
199	        // The household id is deterministic: owners with the same normalized last name and
200	        // postcode share it automatically. Assign it unconditionally before the duplicate
201	        // checks so both the household-duplicate rule and the identity-key rule key off the
202	        // same computed id.
203	        owner.setHouseholdId(householdResolver.householdId(owner));
204	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
205	        boolean householdMember = householdResolver.householdExists(owner);
206	        // Because the household is keyed on (lastName, postcode), a second owner sharing an
207	        // existing owner's household is a household duplicate and is rejected with 409. The
208	        // 'sharesHousehold' flag only bypasses this block, declaring a deliberate member; it
209	        // no longer creates the link, which the deterministic id now does on its own.
210	        if (householdMember && !sharesHousehold) {
211	            return new ResponseEntity<>(HttpStatus.CONFLICT);
212	        }
213	        if (isDuplicateOwner(owner)) {
214	            return new ResponseEntity<>(HttpStatus.CONFLICT);
215	        }
216	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
217	        long ownersInCity = this.clinicService.findAllOwners().stream()
218	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
219	            .count();
220	        if (ownersInCity >= 50) {
221	            return new ResponseEntity<>(HttpStatus.CONFLICT);
222	        }
223	        owner.setCustomerCode(customerCode(owner));
224	        owner.setNamesakeCount(namesakeCount(owner));
225	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
226	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
227	        // Soft-match: the candidate has already cleared the hard-duplicate check, but it may
228	        // still share an existing owner's last name and postcode while carrying a different
229	        // telephone. When it does, it is created but flagged as a possible duplicate of that
230	        // existing owner; otherwise the flag is false and no reference is recorded. A declared
231	        // household member (created via 'sharesHousehold') is not a suspected duplicate, so it
232	        // is never flagged.
233	        Integer possibleDuplicateOf = (sharesHousehold && householdMember) ? null : possibleDuplicateOf(owner);
234	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
235	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
236	        this.clinicService.saveOwner(owner);
237	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
238	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
239	            ownerMapper.membershipLevel(owner));
240	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
241	        headers.setLocation(UriComponentsBuilder.newInstance()
242	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
243	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
244	    }
245	
246	    /**
247	     * Whether {@code candidate} collides with an already-registered owner under the single
248	     * identity rule enforced on create. This is the one point at which a new owner is
249	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
250	     * derived {@link OwnerMapper#identityKey identityKey} — the normalized telephone, the
251	     * email (or an empty string when absent) and the householdId joined by '|'. The
252	     * candidate clashes only when its WHOLE identityKey equals an existing owner's; because
253	     * the telephone is part of the key, two members of the same household (same householdId)
254	     * with different telephones have different identityKeys and are both allowed.
255	     *
256	     * <p>The candidate arrives with its telephone and email already normalized and its
257	     * household id already derived, and each existing owner is stored in the same canonical
258	     * form, so an identityKey match means the two owners are genuinely the same identity.
259	     *
260	     * @param candidate the fully-normalized owner about to be created
261	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
262	     */
263	    private boolean isDuplicateOwner(Owner candidate) {
264	        String identityKey = OwnerMapper.identityKey(candidate);
265	        return this.clinicService.findAllOwners().stream()
266	            .map(OwnerMapper::identityKey)
267	            .anyMatch(identityKey::equals);
268	    }
269	
270	    /**
271	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
272	     * {@code null} when there is none. A soft match is an owner that is not a hard duplicate
273	     * (its whole identityKey differs) yet shares the candidate's normalized last name and its
274	     * postcode while carrying a different telephone — a likely re-registration of the same
275	     * person under a new number. Both must supply a postcode for a match to be possible; when
276	     * several existing owners qualify the lowest id is returned so the result is deterministic.
277	     *
278	     * @param candidate the fully-normalized owner about to be created
279	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
280	     */
281	    private Integer possibleDuplicateOf(Owner candidate) {
282	        String postcode = candidate.getPostcode();
283	        if (postcode == null) {
284	            return null;
285	        }
286	        String lastNameKey = IdentityUtils.normalizeIdentity(candidate.getLastName());
287	        return this.clinicService.findAllOwners().stream()
288	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getLastName()).equals(lastNameKey)
289	                && postcode.equals(existing.getPostcode())
290	                && !postcode.isBlank()
291	                && !java.util.Objects.equals(candidate.getTelephone(), existing.getTelephone()))
292	            .map(Owner::getId)
293	            .filter(java.util.Objects::nonNull)
294	            .min(Integer::compareTo)
295	            .orElse(null);
296	    }
297	
298	    /**
299	     * Build the customer code assigned to {@code owner} on create, formatted
300	     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
301	     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
302	     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
303	     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
304	     */
305	    private String customerCode(Owner owner) {
306	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
307	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
308	        return region + "-" + hash8;
309	    }
310	
311	    /**
312	     * The number of existing owners that share {@code owner}'s firstName and lastName,
313	     * compared case-insensitively. The candidate is not yet stored at the point this is
314	     * assigned, so it does not count itself. This is the value stored as the owner's
315	     * namesakeCount on create.
316	     */
317	    private int namesakeCount(Owner owner) {
318	        return (int) this.clinicService.findAllOwners().stream()
319	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
320	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
321	            .count();
322	    }
323	
324	    /**
325	     * Roll a registration date forward to the next business day: a Saturday or Sunday
326	     * advances to the following Monday, and a weekday is returned unchanged.
327	     */
328	    private static LocalDate toBusinessDay(LocalDate date) {
329	        return switch (date.getDayOfWeek()) {
330	            case SATURDAY -> date.plusDays(2);
331	            case SUNDAY -> date.plusDays(1);
332	            default -> date;
333	        };
334	    }
335	
336	    /**
337	     * Build the membership number assigned on create, formatted
338	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
339	     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
340	     */
341	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
342	        String yy = String.format("%02d", registrationDate.getYear() % 100);
343	        return customerCode + "-M" + yy;
344	    }
345	
346	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
347	    @Override
348	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
349	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
350	        if (currentOwner == null) {
351	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
352	        }
353	        currentOwner.setAddress(ownerFieldsDto.getAddress());
354	        currentOwner.setCity(ownerFieldsDto.getCity());
355	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
356	        currentOwner.setLastName(ownerFieldsDto.getLastName());
357	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
358	        this.clinicService.saveOwner(currentOwner);
359	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
360	    }
361	
362	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
363	    @Transactional
364	    @Override
365	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
366	        Owner owner = this.clinicService.findOwnerById(ownerId);
367	        if (owner == null) {
368	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
369	        }
370	        this.clinicService.deleteOwner(owner);
371	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
372	    }
373	
374	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
375	    @Override
376	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
377	        Owner owner = this.clinicService.findOwnerById(ownerId);
378	        if (owner == null) {
379	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
380	        }
381	        HttpHeaders headers = new HttpHeaders();
382	        Pet pet = petMapper.toPet(petFieldsDto);
383	        owner.setId(ownerId);
384	        pet.setOwner(owner);
385	        pet.getType().setName(null);
386	        this.clinicService.savePet(pet);
387	        PetDto petDto = petMapper.toPetDto(pet);
388	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
389	            .buildAndExpand(pet.getId()).toUri());
390	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
391	    }
392	
393	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
394	    @Override
395	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
396	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
397	        if (currentOwner != null) {
398	            Pet currentPet = this.clinicService.findPetById(petId);
399	            if (currentPet != null) {
400	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
401	                currentPet.setName(petFieldsDto.getName());
402	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
403	                this.clinicService.savePet(currentPet);
404	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
405	            }
406	        }
407	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
408	    }
409	
410	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
411	    @Override
412	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
413	        HttpHeaders headers = new HttpHeaders();
414	        Visit visit = visitMapper.toVisit(visitFieldsDto);
415	        Pet pet = new Pet();
416	        pet.setId(petId);
417	        visit.setPet(pet);
418	        this.clinicService.saveVisit(visit);
419	        VisitDto visitDto = visitMapper.toVisitDto(visit);
420	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
421	            .buildAndExpand(visit.getId()).toUri());
422	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
423	    }
424	
425	
426	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
427	    @Override
428	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
429	        Owner owner = this.clinicService.findOwnerById(ownerId);
430	        if (owner != null) {
431	            Pet pet = owner.getPet(petId);
432	            if (pet != null) {
433	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
434	            }
435	        }
436	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
437	    }
438	}
